import json, math
from PIL import Image

img = Image.open('barcode.png').convert('RGB')
w, h = img.size
px = img.load()
SW = 6
N = math.ceil(w / SW)
barcode = []
for s in range(N):
    x0, x1 = s * SW, min((s + 1) * SW, w)
    rs = gs = bs = cnt = 0
    for x in range(x0, x1):
        for y in range(h):
            p = px[x, y]
            rs += p[0]; gs += p[1]; bs += p[2]
    cnt = (x1 - x0) * h
    barcode.append((rs / cnt, gs / cnt, bs / cnt))

data = json.load(open('frames2.json'))

def resample(frames, interval, dur, N, shift=0):
    # only use frames whose window [t0,t1) intersects [0,dur)
    out = []
    for s in range(N):
        a = s * dur / N
        b = (s + 1) * dur / N
        acc = [0.0, 0.0, 0.0]; wsum = 0.0
        for i, fr in enumerate(frames):
            t0 = (i + shift) * interval
            t1 = t0 + interval
            if t0 >= dur and shift >= 0:
                break
            ov = max(0.0, min(b, t1) - max(a, t0))
            if ov > 0:
                for k in range(3):
                    acc[k] += fr[k] * ov
                wsum += ov
        if wsum > 0:
            out.append(tuple(v / wsum for v in acc))
        else:
            tm = min(max((a + b) / 2, 0), dur - 0.01)
            i = min(len(frames) - 1, max(0, round(tm / interval) - shift))
            out.append(tuple(frames[i]))
    return out

def mean_abs_diff(A, B):
    return sum(abs(A[i][k] - B[i][k]) for i in range(len(A)) for k in range(3)) / (len(A) * 3)

def luma(c):
    return 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]

def corr(a, b):
    n = len(a)
    ma = sum(a) / n; mb = sum(b) / n
    cov = sum((x - ma) * (y - mb) for x, y in zip(a, b))
    va = sum((x - ma) ** 2 for x in a); vb = sum((y - mb) ** 2 for y in b)
    if va == 0 or vb == 0:
        return 0.0
    return cov / math.sqrt(va * vb)

sims = {}
print(f"{'key':18s} {'MAD':>6s} {'shift':>5s} {'lumaCorr':>8s} {'chromaMAD':>9s}")
for key, d in data.items():
    best = None
    for shift in range(-5, 6):
        sim = resample(d["frames"], d["interval"], d["dur"], N, shift)
        sc = mean_abs_diff(sim, barcode)
        if best is None or sc < best[0]:
            best = (sc, shift, sim)
    sims[key] = best
for key, (sc, shift, sim) in sorted(sims.items(), key=lambda kv: kv[1][0]):
    lc = corr([luma(c) for c in sim], [luma(c) for c in barcode])
    cm = sum(abs(sim[i][0] - sim[i][1] - (barcode[i][0] - barcode[i][1])) +
             abs(sim[i][2] - sim[i][1] - (barcode[i][2] - barcode[i][1])) for i in range(N)) / (N * 2)
    print(f"{key:18s} {sc:6.2f} {shift:5d} {lc:8.3f} {cm:9.2f}")

